/* ============================================
   QUOTE COMPONENT
   Inline blockquote or large pull-quote with
   optional attribution.
   ============================================ */

.ds-quote {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: var(--gap-200);
}

.ds-quote__text {
  margin: 0;
}

/* ============================================
   VARIANT — DEFAULT (inline blockquote)
   ============================================ */

.ds-quote--default .ds-quote__text {
  padding-left: var(--padding-500);
  border-left: var(--border-050) solid var(--color-bg-container-tertiary);
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-secondary);
}

.ds-quote--default .ds-quote__caption {
  padding-left: var(--padding-500);
}

/* ============================================
   VARIANT — PULL (large display quote)
   Display type per the weight-contrast rule —
   no border, the scale is the emphasis.
   ============================================ */

.ds-quote--pull .ds-quote__text {
  font-family: var(--font-sub-display-family);
  font-size: var(--font-sub-display-size);
  font-weight: var(--font-sub-display-weight);
  line-height: var(--font-sub-display-line-height);
  letter-spacing: var(--font-sub-display-letter-spacing);
  color: var(--color-text-primary);
}

/* ============================================
   ATTRIBUTION
   ============================================ */

.ds-quote__caption {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
}

.ds-quote__attribution {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  color: var(--color-text-primary);
}

.ds-quote__detail {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
}

import React from 'react';
import './Quote.css';

export interface QuoteProps {
  /** The quote text */
  children: React.ReactNode;
  /** Who said it, e.g. "Jordan Reyes" */
  attribution?: string;
  /** Context under the attribution, e.g. "Design Lead, Northlight" */
  detail?: string;
  /** `default` is an inline blockquote; `pull` is a large display pull-quote */
  variant?: 'default' | 'pull';
  /** Additional CSS classes */
  className?: string;
}

/**
 * Quote component — an inline blockquote or a large pull-quote,
 * with optional attribution.
 */
export const Quote = ({
  children,
  attribution,
  detail,
  variant = 'default',
  className = '',
}: QuoteProps) => {
  const baseClass = 'ds-quote';

  const classes = [baseClass, `${baseClass}--${variant}`, className]
    .filter(Boolean)
    .join(' ');

  return (
    <figure className={classes}>
      <blockquote className={`${baseClass}__text`}>{children}</blockquote>
      {(attribution || detail) && (
        <figcaption className={`${baseClass}__caption`}>
          {attribution && (
            <span className={`${baseClass}__attribution`}>&mdash; {attribution}</span>
          )}
          {detail && <span className={`${baseClass}__detail`}>{detail}</span>}
        </figcaption>
      )}
    </figure>
  );
};
